$:set -euo pipefail
git fetch --quiet origin main
node <<'NODE'
"use strict";
const fs=require("node:fs");
const {execFileSync,spawnSync}=require("node:child_process");
const {createHash}=require("node:crypto");
const repo="BestNameYet/Terminals";
const dest="workspaces/codespace-terminal-mcp/version-manifest.json";
const git=(...args)=>execFileSync("git",args,{encoding:"utf8"}).trim();
const gh=(...args)=>{const res=spawnSync("gh",args,{encoding:"utf8",maxBuffer:16*1024*1024});if(res.status!==0)throw Error("gh command failed: "+(res.stderr||res.error?.message||"unknown"));return JSON.parse(res.stdout)};
const rootCommit=git("rev-parse","FETCH_HEAD");
const remoteSha=gh("api","repos/"+repo+"/git/ref/heads/main").object.sha;
if(rootCommit!==remoteSha)throw Error("main changed during manifest preparation; re-evaluate source tree");
const entrySpecs=[
  [".devcontainer/devcontainer.json","codespace_environment","Codespaces creation or rebuild reads container settings and lifecycle commands","codespace_build_or_rebuild"],
  ["workspaces/codespace-terminal-mcp/package.json","module_and_install_metadata","Node package-scope resolution and npm installation/start entrypoint","startup_and_alternate_stdio"],
  ["workspaces/codespace-terminal-mcp/start-mcp.sh","startup_script","Codespace postStartCommand executes the startup script","codespace_start"],
  ["workspaces/codespace-terminal-mcp/supervise-mcp.sh","supervisor_script","start-mcp.sh starts the supervisor and the shell reads this script","server_launch"],
  ["workspaces/codespace-terminal-mcp/http-server.mjs","http_entrypoint","Supervisor launches node http-server.mjs; Node loads this entrypoint","http_start"],
  ["workspaces/codespace-terminal-mcp/oauth.mjs","http_module","Imported and evaluated by http-server.mjs on startup","http_start"],
  ["workspaces/codespace-terminal-mcp/response-template.mjs","response_module","Imported and evaluated by HTTP entrypoint or optional stdio entrypoint","http_or_stdio_start"],
  ["workspaces/codespace-terminal-mcp/response-template.json","response_configuration","response-template.mjs reads the JSON on MCP tool and resource requests","request_conditional"],
  ["workspaces/codespace-terminal-mcp/terminal.html","ui_resource","http-server.mjs reads this file when ui://terminals/codespace-terminal.html is requested","resource_request_conditional"],
  ["references/account-custom-instructions.json","embedded_resource","response-template.mjs reads this referenced file for embedded account instructions and resource reads","request_conditional"],
  ["workspaces/codespace-terminal-mcp/server.mjs","alternate_stdio_entrypoint","Node loads this file if npm start selects the package's stdio server; not the Codespace HTTP supervisor's entrypoint","alternate_stdio_start"]
];
const entries=entrySpecs.map(([path,role,read_evidence,read_condition])=>{
 const file=execFileSync("git",["show",rootCommit+":"+path],{maxBuffer:32*1024*1024});
 return {path,role,read_condition,read_evidence,
     sha256:createHash("sha256").update(file).digest("hex"),
     git_blob_oid:git("rev-parse",rootCommit+":"+path),
     byte_length:file.length};
});
const packageFile=JSON.parse(execFileSync("git",["show",rootCommit+":workspaces/codespace-terminal-mcp/package.json"],{encoding:"utf8"}));
const manifest={
 schema:"terminals.mcp.runtime-version-manifest.v1",
 manifest_format_version:"1.0.0",
 application_name:packageFile.name,
 application_version:packageFile.version,
 repository:repo,
 authoritative_branch:"main",
 source_commit:rootCommit,
 scope:{
  definition:"Repository-maintained files read by the MCP application's HTTP or alternative stdio lifecycle, startup, package resolution, configured resources, or Codespaces initialization.",
  source_of_evidence:"Static trace of committed entrypoints, import statements, shell scripts, Codespace configuration, and explicit filesystem read operations; conditional reads are included, not asserted observed in a live request.",
  excluded:"Third-party Node packages, Node and operating-system internals, generated dependency trees, test-only files, and arbitrary files read by user-supplied terminal commands. Referenced documents not actually loaded by the MCP server are excluded.",
  version_identity:"Each file is pinned by SHA-256 of the committed bytes and by the Git blob object ID; the source commit identifies the snapshot from which all entries were computed."
 },
 files:entries,
 unversioned_runtime_data:[
  {path_template:"/workspaces/.terminals-mcp/<codespace_name>/oauth.json",read_when:"OAuth module initializes and the MCP_AUTH_STATE_FILE environment variable points here",reason:"Per-instance mutable OAuth state, not authored source; must not be included in a public version manifest or hashed into published source."},
  {path_template:"$HOME/.local/share/terminals-mcp/oauth.json",read_when:"OAuth initialization falls back to the legacy state file if the configured path is missing",reason:"Legacy mutable OAuth state; not authored source."},
  {path_template:"<configured_MCP_AUTH_STATE_FILE>",read_when:"MCP_AUTH_STATE_FILE overrides the OAuth state location",reason:"An environment-configured mutable data file, not a versioned implementation file."}
 ],
 dependency_boundary:{
  source_of_external_dependencies:"workspaces/codespace-terminal-mcp/package.json",
  rule:"Version only repository-maintained MCP implementation inputs. Dependencies and arbitrary terminal-command operands are outside this implementation manifest."
 }
};
const body=JSON.stringify(manifest,null,2)+"\n";
fs.writeFileSync("/tmp/terminals-mcp-version-manifest.json",body);
try{
 const existing=gh("api","repos/"+repo+"/contents/"+dest);
 throw Error("Manifest already exists at GitHub main (blob "+existing.sha+"); refusing blind overwrite");
}catch(e){if(!String(e).includes("HTTP 404"))throw e}
const before=gh("api","repos/"+repo+"/git/ref/heads/main").object.sha;
if(before!==rootCommit)throw Error("main advanced before write");
const created=gh("api","-X","PUT","repos/"+repo+"/contents/"+dest,
 "-f","message=Add MCP runtime version manifest of repository-maintained file reads",
 "-f","branch=main","-f","content="+Buffer.from(body,"utf8").toString("base64"));
const checked=gh("api","repos/"+repo+"/contents/"+dest);
const stored=Buffer.from(checked.content.replace(/\s/g,""),"base64").toString("utf8");
if(stored!==body)throw Error("Version manifest readback mismatch");
console.log(JSON.stringify({status:"CREATED_AND_READBACK_VERIFIED",path:dest,source_commit:rootCommit,
 manifest_commit:created.commit?.sha,git_blob_oid:created.content?.sha,
 tracked_file_count:entries.length,unversioned_runtime_data_count:manifest.unversioned_runtime_data.length,
 manifest_sha256:createHash("sha256").update(body).digest("hex")}));

NODE
